//! The account registry — and, more usefully, what it CANNOT tell you.
//!
//! `position` needs to know what each account IS before a balance means anything: whether a positive
//! number is money you have or money you owe, what the credit limit is, what rate it carries. None of
//! that is in a statement export, and until now nothing recorded it — so the analysis existed and had
//! no way to be handed the one thing it needed.
//!
//! # The half that matters to an agent is `gaps`
//!
//! A session driving these systems cannot see a screen. It needs to know not just what is stored but
//! WHAT IS MISSING AND WHAT THAT COSTS — that an absent APR is why there is no interest figure, that
//! an absent credit limit is why utilisation is silent. A registry that only answered "here is what I
//! have" would leave the agent guessing at why a downstream number never appeared, and guessing is
//! how a default gets invented.
//!
//! So every gap names the capability it blocks. That is the difference between a store and an
//! instrument.
//!
//! # An account NUMBER never enters this
//!
//! Refused at any depth, the same way `bsc secret set` refuses a secret-bearing key. The registry
//! needs to know that an account is a credit card at 24.99% with a $5,000 limit; it never needs the
//! digits, and a store that accepts them becomes a file worth stealing.
use std::collections::BTreeMap;

/// What kind of thing an account is — which decides whether a positive balance is held or owed.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum Kind {
    Checking,
    Savings,
    Credit,
    Loan,
    Investment,
}

impl Kind {
    pub fn as_str(self) -> &'static str {
        match self {
            Kind::Checking => "checking",
            Kind::Savings => "savings",
            Kind::Credit => "credit",
            Kind::Loan => "loan",
            Kind::Investment => "investment",
        }
    }

    pub fn parse(s: &str) -> Option<Kind> {
        Some(match s {
            "checking" => Kind::Checking,
            "savings" => Kind::Savings,
            "credit" => Kind::Credit,
            "loan" => Kind::Loan,
            "investment" => Kind::Investment,
            _ => return None,
        })
    }

    /// True where a positive printed balance means money you OWE.
    pub fn is_debt(self) -> bool {
        matches!(self, Kind::Credit | Kind::Loan)
    }

    /// True where it can pay a bill this week. An investment cannot.
    pub fn is_liquid(self) -> bool {
        matches!(self, Kind::Checking | Kind::Savings)
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Account {
    /// The key everything else joins on — and the name a statement file starts with.
    pub id: String,
    pub institution: String,
    pub kind: Kind,
    pub currency: String,
    /// Minor units, positive. NONE means unknown, which is not the same as no limit.
    pub credit_limit: Option<i64>,
    /// Annual rate in basis points — 2499 for 24.99%. Integer, because a rate in a float is the
    /// same defect class as money in a float.
    pub apr_bps: Option<u32>,
    /// Minor units the institution will accept this cycle.
    pub minimum_payment: Option<i64>,
    /// Day of month the statement closes, where it is known.
    pub statement_day: Option<u8>,
    pub note: Option<String>,
}

/// Something the registry does not know, and the capability that cannot run without it.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Gap {
    pub account: String,
    pub field: &'static str,
    /// What silently does not happen. Named, because the agent's next question is always "why is
    /// there no number here".
    pub blocks: &'static str,
}

/// Keys that must never be stored. The registry needs the SHAPE of an account, never its identity.
const FORBIDDEN: &[&str] = &[
    "number", "account_number", "accountnumber", "acct", "pan", "card_number", "cardnumber",
    "routing", "routing_number", "iban", "ssn", "tax_id", "taxid", "pin", "cvv", "password", "secret", "token",
];

/// Whether any key ANYWHERE in a JSON value is one the registry refuses.
///
/// A GUARD, not a filter. Silently dropping an account number would let a caller keep writing the
/// code that sends one.
pub fn forbidden_key(value: &serde_json::Value) -> Option<String> {
    match value {
        serde_json::Value::Object(map) => {
            for (k, v) in map {
                let lower = k.to_ascii_lowercase();
                if FORBIDDEN.iter().any(|f| lower == *f) {
                    return Some(k.clone());
                }
                if let Some(hit) = forbidden_key(v) {
                    return Some(hit);
                }
            }
            None
        }
        serde_json::Value::Array(xs) => xs.iter().find_map(forbidden_key),
        _ => None,
    }
}

/// Read one account from JSON, refusing what it must not hold.
pub fn from_json(v: &serde_json::Value) -> Result<Account, String> {
    if let Some(k) = forbidden_key(v) {
        return Err(format!(
            "`{k}` is not something this store will hold. The registry needs to know an account's SHAPE — kind, limit, rate — never its identity, and a store that accepts the digits becomes a file worth stealing."
        ));
    }
    let s = |k: &str| v.get(k).and_then(|x| x.as_str()).map(str::to_string);
    let n = |k: &str| v.get(k).and_then(serde_json::Value::as_i64);
    let id = s("id").ok_or_else(|| "an account needs an `id` — the name its statement files start with".to_string())?;
    let kind_raw = s("kind").ok_or_else(|| format!("{id}: `kind` is required — without it a positive balance could be money held or money owed"))?;
    let kind = Kind::parse(&kind_raw)
        .ok_or_else(|| format!("{id}: `{kind_raw}` is not a kind — one of checking, savings, credit, loan, investment"))?;
    Ok(Account {
        institution: s("institution").unwrap_or_else(|| id.clone()),
        currency: s("currency").unwrap_or_else(|| "USD".to_string()),
        credit_limit: n("creditLimit"),
        apr_bps: n("aprBps").and_then(|x| u32::try_from(x).ok()),
        minimum_payment: n("minimumPayment"),
        statement_day: n("statementDay").and_then(|x| u8::try_from(x).ok()).filter(|d| (1..=31).contains(d)),
        note: s("note"),
        id,
        kind,
    })
}

pub fn to_json(a: &Account) -> serde_json::Value {
    serde_json::json!({
        "id": a.id,
        "institution": a.institution,
        "kind": a.kind.as_str(),
        "currency": a.currency,
        "creditLimit": a.credit_limit,
        "aprBps": a.apr_bps,
        "minimumPayment": a.minimum_payment,
        "statementDay": a.statement_day,
        "note": a.note,
        // DERIVED, so a reader does not have to know the kind table to act on the row.
        "isDebt": a.kind.is_debt(),
        "isLiquid": a.kind.is_liquid(),
    })
}

pub fn all_to_json(accounts: &[Account]) -> serde_json::Value {
    serde_json::Value::Array(accounts.iter().map(to_json).collect())
}

/// Read a whole registry back. An entry that cannot be read is DROPPED with its id reported rather
/// than defaulted into something plausible.
pub fn all_from_json(v: &serde_json::Value) -> (Vec<Account>, Vec<String>) {
    let mut out = Vec::new();
    let mut rejected = Vec::new();
    for item in v.as_array().map(Vec::as_slice).unwrap_or_default() {
        match from_json(item) {
            Ok(a) => out.push(a),
            Err(e) => rejected.push(e),
        }
    }
    out.sort_by(|a, b| a.id.cmp(&b.id));
    (out, rejected)
}

/// Replace one account, keeping every other. Sorted, so the file is stable and a diff means something.
pub fn upsert(accounts: &mut Vec<Account>, next: Account) {
    match accounts.iter_mut().find(|a| a.id == next.id) {
        Some(slot) => *slot = next,
        None => accounts.push(next),
    }
    accounts.sort_by(|a, b| a.id.cmp(&b.id));
}

/// WHAT IS MISSING, AND WHAT IT COSTS.
///
/// The instrument half. Each gap names the capability that silently does not run without it, because
/// an agent's next question after a missing number is always "why", and without an answer it invents
/// one.
pub fn gaps(accounts: &[Account]) -> Vec<Gap> {
    let mut out = Vec::new();
    for a in accounts {
        if a.kind == Kind::Credit && a.credit_limit.is_none() {
            out.push(Gap {
                account: a.id.clone(),
                field: "creditLimit",
                blocks: "utilisation — which is UNKNOWN rather than 0%, and 0% is an excellent score while not knowing is not",
            });
        }
        if a.kind.is_debt() && a.apr_bps.is_none() {
            out.push(Gap {
                account: a.id.clone(),
                field: "aprBps",
                blocks: "daily interest, the weighted APR, and the avalanche order — the payoff plan cannot rank a debt whose rate it does not know",
            });
        }
        if a.kind.is_debt() && a.minimum_payment.is_none() {
            out.push(Gap {
                account: a.id.clone(),
                field: "minimumPayment",
                blocks: "the obligation calendar and the minimums-first rule — a missed minimum is a credit event",
            });
        }
        if a.kind.is_debt() && a.statement_day.is_none() {
            out.push(Gap {
                account: a.id.clone(),
                field: "statementDay",
                blocks: "the due date — the calendar falls back to the 1st, the earliest it could plausibly be, so nothing reads as late that is not",
            });
        }
    }
    out.sort_by(|x, y| x.account.cmp(&y.account).then(x.field.cmp(y.field)));
    out
}

/// How much of the picture is actually known, as a count — the one number an agent can act on
/// without reading every row.
pub fn completeness(accounts: &[Account]) -> (usize, usize) {
    let missing = gaps(accounts).len();
    let possible: usize = accounts
        .iter()
        .map(|a| match a.kind {
            Kind::Credit => 4,
            Kind::Loan => 3,
            _ => 0,
        })
        .sum();
    (possible.saturating_sub(missing), possible)
}

/// Every account referenced by a statement that the registry has never heard of.
///
/// The other direction of the same question: not "what do I not know about this account" but "what
/// account do I not know about at all".
pub fn undeclared<'a>(accounts: &[Account], seen: impl IntoIterator<Item = &'a str>) -> Vec<String> {
    let known: BTreeMap<&str, ()> = accounts.iter().map(|a| (a.id.as_str(), ())).collect();
    let mut out: Vec<String> = seen
        .into_iter()
        .filter(|s| !known.contains_key(*s))
        .map(str::to_string)
        .collect();
    out.sort();
    out.dedup();
    out
}

/// What a person reads. Gaps are NOT a footnote — they are most of the value.
pub fn render(accounts: &[Account]) -> String {
    if accounts.is_empty() {
        return "no accounts declared — `position` cannot say whether a balance is held or owed until one is\n".to_string();
    }
    let mut out = String::new();
    for a in accounts {
        let rate = a.apr_bps.map(|b| format!("{}.{:02}%", b / 100, b % 100)).unwrap_or_else(|| "rate unknown".into());
        out.push_str(&format!("  {:<18} {:<12} {:<16} {}\n", a.id, a.kind.as_str(), a.institution, rate));
    }
    let g = gaps(accounts);
    let (known, possible) = completeness(accounts);
    out.push_str(&format!("\n{known} of {possible} facts known about the debts.\n"));
    if !g.is_empty() {
        out.push_str("\nMissing, and what each one costs:\n");
        for x in &g {
            out.push_str(&format!("  {} · {} — blocks {}\n", x.account, x.field, x.blocks));
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    // SYNTHETIC FIXTURES ONLY. No real account, limit or rate belongs in this repo.
    fn card() -> Account {
        Account {
            id: "discover".into(),
            institution: "Discover".into(),
            kind: Kind::Credit,
            currency: "USD".into(),
            credit_limit: Some(500_000),
            apr_bps: Some(2499),
            minimum_payment: Some(9_000),
            statement_day: Some(14),
            note: None,
        }
    }

    fn bare_card() -> Account {
        Account { credit_limit: None, apr_bps: None, minimum_payment: None, statement_day: None, ..card() }
    }

    #[test]
    fn an_account_number_is_refused_at_any_depth() {
        // The registry needs an account's SHAPE, never its identity. A store that accepts the digits
        // becomes a file worth stealing.
        for key in ["number", "accountNumber", "routing", "ssn", "pan", "cvv"] {
            let v = serde_json::json!({ "id": "x", "kind": "credit", key: "4111111111111111" });
            let e = from_json(&v).unwrap_err();
            assert!(e.contains("worth stealing"), "{key}: {e}");
        }
        let nested = serde_json::json!({ "id": "x", "kind": "credit", "meta": { "deep": { "ssn": "1" } } });
        assert!(from_json(&nested).is_err());
    }

    #[test]
    fn the_refusal_is_a_guard_not_a_filter() {
        // Silently dropping the field would let a caller keep writing the code that sends one.
        let v = serde_json::json!({ "id": "x", "kind": "credit", "number": "4111" });
        assert!(from_json(&v).is_err());
        assert_eq!(forbidden_key(&v).as_deref(), Some("number"));
    }

    #[test]
    fn kind_is_required_because_a_balance_is_meaningless_without_it() {
        let e = from_json(&serde_json::json!({ "id": "x" })).unwrap_err();
        assert!(e.contains("money held or money owed"), "{e}");
        let e2 = from_json(&serde_json::json!({ "id": "x", "kind": "brokerage" })).unwrap_err();
        assert!(e2.contains("not a kind"), "{e2}");
    }

    #[test]
    fn a_round_trip_loses_nothing() {
        let back = from_json(&to_json(&card())).unwrap();
        assert_eq!(back, card());
        let bare = from_json(&to_json(&bare_card())).unwrap();
        assert_eq!(bare, bare_card());
    }

    #[test]
    fn the_wire_shape_carries_the_derived_facts_so_a_reader_need_not_know_the_kind_table() {
        let v = to_json(&card());
        assert_eq!(v["isDebt"], true);
        assert_eq!(v["isLiquid"], false);
        let cash = Account { id: "checking".into(), kind: Kind::Checking, ..card() };
        assert_eq!(to_json(&cash)["isLiquid"], true);
        assert_eq!(to_json(&cash)["isDebt"], false);
    }

    #[test]
    fn every_gap_names_what_it_blocks() {
        // An agent's next question after a missing number is always "why", and without an answer it
        // invents one.
        let g = gaps(&[bare_card()]);
        assert_eq!(g.len(), 4);
        assert!(g.iter().all(|x| !x.blocks.is_empty()));
        let by_field: Vec<&str> = g.iter().map(|x| x.field).collect();
        assert_eq!(by_field, ["aprBps", "creditLimit", "minimumPayment", "statementDay"]);
        assert!(g.iter().find(|x| x.field == "creditLimit").unwrap().blocks.contains("0% is an excellent score"));
        assert!(g.iter().find(|x| x.field == "aprBps").unwrap().blocks.contains("avalanche order"));
    }

    #[test]
    fn a_complete_card_has_no_gaps_and_a_cash_account_never_does() {
        assert_eq!(gaps(&[card()]), vec![]);
        let cash = Account { id: "checking".into(), kind: Kind::Checking, ..bare_card() };
        // A chequing account has no rate, no limit and no minimum, and demanding them would fill the
        // report with work nobody can do.
        assert_eq!(gaps(&[cash]), vec![]);
    }

    #[test]
    fn completeness_counts_only_what_could_be_known() {
        assert_eq!(completeness(&[card()]), (4, 4));
        assert_eq!(completeness(&[bare_card()]), (0, 4));
        let cash = Account { id: "checking".into(), kind: Kind::Checking, ..bare_card() };
        assert_eq!(completeness(&[cash]), (0, 0));
    }

    #[test]
    fn undeclared_answers_the_other_direction_of_the_question() {
        // Not "what do I not know about this account" but "what account do I not know about at all".
        let out = undeclared(&[card()], ["discover", "chase", "chase", "capital-one"]);
        assert_eq!(out, ["capital-one", "chase"]);
        assert!(undeclared(&[card()], ["discover"]).is_empty());
    }

    #[test]
    fn a_row_that_cannot_be_read_is_dropped_with_its_reason_not_defaulted() {
        let v = serde_json::json!([
            { "id": "good", "kind": "credit" },
            { "id": "bad" },
            { "id": "worse", "kind": "credit", "ssn": "1" },
        ]);
        let (ok, rejected) = all_from_json(&v);
        assert_eq!(ok.len(), 1);
        assert_eq!(ok[0].id, "good");
        assert_eq!(rejected.len(), 2);
    }

    #[test]
    fn upsert_replaces_one_and_keeps_the_rest_sorted() {
        let mut xs = vec![card()];
        upsert(&mut xs, Account { id: "amex".into(), ..bare_card() });
        upsert(&mut xs, Account { apr_bps: Some(1999), ..card() });
        assert_eq!(xs.len(), 2);
        assert_eq!(xs.iter().map(|a| a.id.as_str()).collect::<Vec<_>>(), ["amex", "discover"]);
        assert_eq!(xs[1].apr_bps, Some(1999));
    }

    #[test]
    fn the_render_leads_with_what_is_missing_rather_than_burying_it() {
        let out = render(&[bare_card()]);
        assert!(out.contains("0 of 4 facts known"), "{out}");
        assert!(out.contains("Missing, and what each one costs"), "{out}");
        assert!(out.contains("rate unknown"), "{out}");
    }

    #[test]
    fn an_empty_registry_says_what_that_costs() {
        assert!(render(&[]).contains("cannot say whether a balance is held or owed"));
    }
}
